from pathlib import Path
import json
O=Path('output/nobogh-v2')
def brand(): return '<a href="landing.html" class="brand" aria-label="نبوغ، الصفحة الرئيسية"><img src="assets/logo.png" alt="شعار نبوغ الأصلي"><span><strong>نبوغ</strong><small>نكتشف. نلعب. ننمو.</small></span></a>'
def head(title,body,cls=''):
 return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' | نبوغ</title><meta name="robots" content="noindex"><link rel="stylesheet" href="design.css"></head><body class="'+cls+'"><a class="skip" href="#main">انتقل إلى المحتوى</a>'+body+'<script src="prototype.js"></script></body></html>'
def demo():return '<div class="prototype-bar">نموذج تصميم تفاعلي · بيانات توضيحية<a href="index.html">دليل النماذج والتقرير ←</a></div>'
def nav():return '<header class="container nav">'+brand()+'<nav class="nav-links" aria-label="التنقل الرئيسي"><a href="landing.html#how">كيف نكتشف؟</a><a href="landing.html#activities">الأنشطة</a><a href="landing.html#family">للأم والطفل</a></nav><div class="actions"><a class="login" href="auth.html">تسجيل الدخول</a><a class="btn pink small" href="auth.html">ابدئي الرحلة ←</a></div></header>'
def shapes():return '<div class="shape-play" aria-hidden="true"><div class="shape circle"></div><div class="shape triangle"></div><div class="shape square tall"></div></div>'
def art():return '<div class="play-art"><div class="arch"></div><img class="hero-photo" src="assets/goals.png" alt="طفلة مبتسمة من الصور المستخدمة في موقع نبوغ"><span class="art-sun" aria-hidden="true">✳</span><div class="art-badge">كل محاولة، اكتشاف!<small>مساحة صغيرة لأفكار كبيرة</small></div><div class="art-card"><div class="shape square tile" aria-hidden="true"></div><span><strong>نلعب معًا، ونفكّر معًا</strong><small class="micro" style="display:block">لحظات تعلّم تصنعانها أنتما</small></span></div><span class="twinkle" aria-hidden="true">✦</span></div>'
def footer():return '<footer class="container footer"><span>نبوغ · لأن كل طفل يكتشف بطريقته.</span><div class="actions"><a href="index.html">عن هذه النماذج</a><a href="report.html">التقرير التفصيلي</a><a href="https://nobogh.net/" target="_blank" rel="noopener">الموقع الحالي ↗</a></div></footer>'
activity_dialog='''<dialog class="dialog" id="activity-dialog"><div class="dialog-body"><div class="dialog-head"><h2>كل شكل له حكاية</h2><button class="icon-btn" data-close aria-label="إغلاق تفاصيل النشاط">×</button></div><div class="actions"><span class="tag">٥–٦ سنوات</span><span class="tag yellow">١٠ دقائق تقريبًا</span></div><p style="margin-top:18px">نتدرّب على ملاحظة التشابه والاختلاف. الوقت والعمر هنا مثال لتقييم التصميم؛ يعتمد المحتوى النهائي على مراجعة تربوية.</p><h3 style="margin-top:20px">جهّزا مساحة صغيرة</h3><p>أشكال ورقية كبيرة أو أشياء مناسبة للعمر من المنزل، مع إشراف ولي الأمر.</p><ol><li>شاهدا الأشكال وسمّيا ما تلاحظانه.</li><li>اجمعا الأشكال المتشابهة معًا.</li><li>اسألي طفلك: كيف اخترت هذه المجموعة؟</li></ol><a class="btn dark full" href="child.html">افتحي مثالًا للطفل ←</a><p class="micro" style="margin-top:12px">نشاط توضيحي قصير لا يقيس ذكاء الطفل أو قدراته.</p></div></dialog>'''
cards=''
for col,cat,title,desc,tag in [('mint','الانتباه والتصنيف','كل شكل له حكاية','نجمع المتشابه، ونكتشف المختلف.','١٠ دقائق'),('pink','الخيال والتعبير','حكاية من ثلاث صور','نرتّب الصور ونحكي قصة بطريقتنا.','٨ دقائق'),('sun','التفكير المنطقي','ماذا يأتي بعد؟','نبحث عن النمط ونكمل المغامرة.','١٢ دقيقة')]:
 cards+=f'<article class="card activity"><div class="activity-art {col}">{shapes()}</div><div class="activity-info"><span class="micro">{cat}</span><h3>{title}</h3><p class="muted">{desc}</p><div class="actions"><span class="tag">{tag}</span><button class="btn line small" '+('data-open="activity-dialog">اكتشفي النشاط' if col=='mint' else 'data-notice="هذه بطاقة اتجاه بصري. يتوفر مثال التصنيف في النشاط الأول.">عن النشاط')+'</button></div></div></article>'
landing=demo()+nav()+f'''<main id="main"><section class="container hero"><div class="hero-copy"><span class="eyebrow">لحظات صغيرة. اكتشافات كبيرة.</span><h1>مع كل لعبة،<br>تكبر <span class="accent">فكرة.</span></h1><p>اكتشفي عالم طفلك، خطوة بخطوة.<br>أنشطة ملهمة تلعبانها معًا، وتفتح له مساحة ليفكّر ويسأل ويجرّب.</p><div class="actions"><button class="btn pink" data-open="activity-dialog">جرّبي نشاطًا مع طفلك <span>←</span></button><a class="btn line" href="#how">كيف تعمل نبوغ؟</a></div><div class="trust-line"><span>خطوات واضحة للأم</span><span>لعب له معنى</span><span>على إيقاع طفلك</span></div></div>{art()}</section><div class="ticker"><span><b>✦</b> نكتشف بالملاحظة</span><span><b>◒</b> نتعلّم بالتجربة</span><span><b>✳</b> ننمو باللعب</span><span><b>♡</b> نصنع لحظات معًا</span></div><section id="activities" class="container section"><div class="section-head"><div><span class="eyebrow">ما الذي سنكتشفه اليوم؟</span><h2>بداية صغيرة تناسب طفلك</h2></div><div class="chip-group" aria-label="الفئة العمرية"><button class="chip" data-age="3-4" aria-pressed="false">٣–٤ سنوات</button><button class="chip" data-age="5-6" aria-pressed="true">٥–٦ سنوات</button><button class="chip" data-age="7-8" aria-pressed="false">٧–٨ سنوات</button></div></div><p class="muted" id="age-copy" role="status" style="margin-bottom:24px">نتدرّب معًا على التصنيف بالأشكال والألوان.</p><div class="cards">{cards}</div><p class="micro" style="margin-top:15px">الأعمار والمدد والأنشطة أمثلة توضيحية إلى حين اعتماد المحتوى التربوي.</p></section><section id="family" class="container"><div id="how" class="family-band"><div><span class="eyebrow">أنتِ شريكته في الاكتشاف</span><h2>لستِ بحاجة إلى إجابة لكل سؤال.<br>فقط مساحة لتكتشفا معًا.</h2><p class="muted" style="margin-top:16px">تمنحك نبوغ فكرة البداية، وخطوات النشاط، ومساحة لتدوّني ما لاحظتِه.</p></div><div class="steps"><div class="step"><span class="step-num">١</span><span><strong>اختاري بداية مناسبة</strong><br>بحسب عمر طفلك واهتمامه.</span></div><div class="step"><span class="step-num">٢</span><span><strong>العبا وجربا معًا</strong><br>خطوات قصيرة وأدوات بسيطة.</span></div><div class="step"><span class="step-num">٣</span><span><strong>احتفظي بلحظة اكتشاف</strong><br>ملاحظة صغيرة تساعدك على اختيار التالي.</span></div></div></div></section></main>'''+footer()+activity_dialog
(O/'landing.html').write_text(head('مع كل لعبة، تكبر فكرة',landing),encoding='utf-8')

def sidebar(active='parent',admin=False):
 links=[('parent.html','⌂','لوحتي اليوم','parent'),('landing.html#activities','◈','اكتشفي الأنشطة','activities'),('parent.html#progress','◔','خطوات التعلّم','progress'),('child.html','✦','مساحة الطفل','child')]
 if admin:links=[('admin.html','▦','نظرة عامة','admin'),('admin.html#requests','☷','طلبات المراجعة','requests'),('admin.html#requests','◈','المحتوى والأنشطة','content')]
 return '<aside class="sidebar">'+brand()+'<nav class="side-links" aria-label="التنقل الجانبي">'+''.join(f'<a class="side-link {"active" if key==active else ""}" href="{url}"><i aria-hidden="true">{ico}</i>{text}</a>' for url,ico,text,key in links)+'</nav><div class="side-foot">'+('مساحة إدارة<br><strong>دور تجريبي: مراجع محتوى</strong>' if admin else 'لحظة تعلّم، والكثير من القرب.<br><strong>كل طفل ينمو بإيقاعه.</strong>')+'</div><a class="micro" href="index.html">العودة إلى دليل النماذج ←</a></aside>'
def header(title):return '<header class="app-header"><span><strong>'+title+'</strong><span class="micro"> · نموذج تفاعلي</span></span><div class="actions"><button class="icon-btn" data-notice="لا توجد تنبيهات جديدة في النموذج." aria-label="الإشعارات">♧</button><span class="profile" aria-label="حساب توضيحي">س</span></div></header>'
mobile='<nav class="mobile-nav" aria-label="التنقل على الهاتف"><a class="active" href="parent.html"><b>⌂</b>اليوم</a><a href="landing.html#activities"><b>◈</b>الأنشطة</a><a href="parent.html#progress"><b>◔</b>التقدّم</a><a href="child.html"><b>✦</b>للطفل</a></nav>'
parent=f'''<div class="app">{sidebar()}<div class="app-body">{header('مساحتك أنتِ وطفلك')}<main id="main" class="workspace"><div class="greeting"><div><span class="eyebrow">يسعدنا أن نكتشف معًا</span><h1>أهلًا سارة، لنصنع لحظة جميلة <span style="color:#8a6600">✳</span></h1><p class="muted">خطوة صغيرة اليوم، ومساحة واسعة للمحاولة.</p></div><div class="child-switch" aria-label="اختيار الطفل"><button class="child-tab" data-child="layan" aria-pressed="true"><span class="avatar">ل</span>ليان · ٥</button><button class="child-tab" data-child="adam" aria-pressed="false"><span class="avatar" style="background:var(--blush)">آ</span>آدم · ٧</button></div></div><section class="hero-task"><div><span class="tag" style="background:#fff">اختيار اليوم لـ <span data-child-name>ليان</span> <span aria-hidden="true">✦</span></span><h2 id="task-title">كل شكل له حكاية</h2><p id="task-description">اختارا ثلاثة أشكال من حولكما، ثم اجمعا الأشكال المتشابهة.</p><div class="actions"><span class="tag">١٠ دقائق تقريبًا</span><span class="tag" id="child-age">٥ سنوات</span><span class="tag">التصنيف والملاحظة</span></div><div class="actions"><a id="child-link" class="btn dark" href="child.html?child=layan">ابدآ الاكتشاف ←</a><button class="btn white" data-open="why-dialog">لماذا هذا النشاط؟</button></div></div><div class="task-art">{shapes()}</div></section><section class="metrics" aria-label="ملخص توضيحي للأنشطة"><div class="metric"><div><span class="micro">أنشطة هذا الأسبوع</span><strong id="activity-count">٤</strong><span class="muted micro">فرص جديدة للمحاولة</span></div><span class="symbol mint" aria-hidden="true">◈</span></div><div class="metric"><div><span class="micro">الاهتمام الأخير</span><strong>الأشكال</strong><span class="muted micro">بحسب الأنشطة المختارة</span></div><span class="symbol pink" aria-hidden="true">◒</span></div><div class="metric"><div><span class="micro">ملاحظتك الأخيرة</span><strong>تجرّب بثقة</strong><span class="muted micro">مثال لملاحظة ولي الأمر</span></div><span class="symbol" aria-hidden="true">✳</span></div></section><div class="lower-grid"><section class="card" id="progress"><div class="section-head" style="margin-bottom:0"><h3>خطوات <span data-child-name>ليان</span> هذا الأسبوع</h3><span class="tag">مثال توضيحي</span></div><p class="micro">سجل للمشاركة في الأنشطة، وليس تقييمًا للقدرات.</p><div class="progress-row"><span>المشاركة</span><div class="progress-track"><b id="weekly-bar" style="width:80%"></b></div><strong id="weekly-count">٤ من ٥ أنشطة</strong></div><p class="muted" style="margin-top:22px">كل نشاط جربتماه فرصة للحوار. لا تحتاجان إلى إكمال كل شيء اليوم.</p></section><section class="card coach"><span class="eyebrow">فكرة لكِ، في المرة القادمة</span><h3>اسألي: «كيف فكّرت؟»</h3><p id="coach-copy">جرّبي أن تطلبي من ليان شرح اختيارها. الحوار حول الفكرة جزء من النشاط.</p><button class="btn white small" data-open="note-dialog">دوّني لحظة اكتشاف +</button></section></div><p class="micro" style="margin-top:20px">كل الأسماء والملاحظات والأعداد بيانات تجريبية؛ لا توجد معلومات أسر حقيقية في هذا النموذج.</p></main></div></div>{mobile}<dialog class="dialog" id="why-dialog"><div class="dialog-body"><div class="dialog-head"><h2>لماذا يظهر هذا النشاط؟</h2><button data-close class="icon-btn" aria-label="إغلاق">×</button></div><p>مثال لتفسير التوصية: يجمع النشاط بين الفئة العمرية المختارة والاهتمام بالأشكال. عند التنفيذ الفعلي، يعرض النظام السبب الحقيقي من بيانات النشاط.</p><p style="margin-top:15px">لا نستنتج مستوى الذكاء أو نشخّص الطفل من عدد الأنشطة.</p></div></dialog><dialog class="dialog" id="note-dialog"><div class="dialog-body"><div class="dialog-head"><h2>لحظة تستحق أن تبقى</h2><button data-close class="icon-btn" aria-label="إغلاق">×</button></div><div class="field"><label for="note">ماذا لاحظتِ أثناء اللعب؟</label><input id="note" placeholder="مثلًا: جرّبت طريقة جديدة لتجميع الأشكال"></div><button class="btn dark full" style="margin-top:20px" data-close data-notice="اكتملت معاينة الملاحظة. لم تُحفظ بيانات خارج هذه الصفحة.">إنهاء المعاينة</button></div></dialog>'''
(O/'parent.html').write_text(head('لوحة الأم',parent),encoding='utf-8')
auth=demo()+nav()+f'''<main class="auth-layout" id="main"><section class="auth-panel"><div class="form-steps"><b>١</b>بدايتك<span class="line-step"></span><b style="background:#eef2ec">٢</b>طفلك</div><span class="eyebrow">مساحة لكما، وخطوة على مهل</span><h1 id="auth-title">تبدأ رحلته، بقربك.</h1><p id="auth-intro" class="muted">لنجهّز لكِ بداية بسيطة لتكتشفا معًا.</p><form id="demo-form"><div id="auth-one"><div class="field"><label for="email">بريد ولي الأمر</label><input id="email" type="email" dir="ltr" placeholder="name@example.com" required autocomplete="email"><p class="micro" style="margin-top:9px">في المنتج النهائي: نرسل رابط تحقق لتأمين الحساب.</p></div><label class="check-line"><input id="consent" type="checkbox" required><span>أفهم أن هذه معاينة تصميم فقط. لن تُرسل رسالة أو يُنشأ حساب حقيقي.</span></label></div><div id="auth-two" hidden><div class="field"><label for="nickname">بمَ نُنادي طفلك؟</label><input id="nickname" maxlength="30" placeholder="اسم مستعار يكفي" autocomplete="off"></div><div class="field"><label for="age">الفئة العمرية</label><select id="age"><option value="">اختاري فئة عمرية</option>٣–٤ سنوات</option><option>٥–٦ سنوات</option><option>٧–٨ سنوات</option></select><p class="micro" style="margin-top:9px">لا نحتاج إلى تاريخ الميلاد الكامل لهذه المعاينة.</p></div></div><button id="auth-submit" class="btn dark full" style="margin-top:22px" type="submit">تابعي إلى الخطوة التالية ←</button></form><p class="micro" style="margin-top:19px;text-align:center">ستظهر بيانات ليان وآدم التوضيحية في لوحة المتابعة.</p><div style="border-top:1px solid var(--line);padding-top:23px;margin-top:23px;text-align:center"><strong>تريدين استكشاف مساحة الطفل؟</strong><br><a class="btn line full" style="margin-top:13px" href="child.html">شاهدي نموذج الطفل ✦</a></div></section><section class="auth-illustration"><h2>أفكار تنمو.<br>وذكريات تبقى.</h2>{art()}<p class="muted">أنتِ تعرفين طفلك. ونبوغ تساعدك على تحويل فضوله إلى لحظة اكتشاف.</p></section></main>'''+footer()
(O/'auth.html').write_text(head('بداية الرحلة',auth,'auth-page'),encoding='utf-8')
child=f'''{demo()}<main id="main" class="child-main"><header class="child-head">{brand()}<a class="btn line" href="parent.html">العودة لولي الأمر ←</a></header><section class="child-hero"><span class="tag white" id="child-greeting">مرحبًا يا ليان!</span><h1 id="child-question">أين تختبئ الدائرة؟</h1><p id="child-instruction">اختر الشكل الذي ليس له زوايا.</p><div class="lesson-progress" aria-label="ثلاث مراحل: اختيار، اكتشاف، انتهاء"><span class="done"></span><span id="progress-two"></span><span id="progress-three"></span></div><div class="choices" aria-label="اختر الشكل"><button class="choice" data-answer="triangle" aria-pressed="false"><span class="shape triangle" aria-hidden="true"></span><span>المثلث</span></button><button class="choice" data-answer="circle" aria-pressed="false"><span class="shape circle" aria-hidden="true"></span><span>الدائرة</span></button><button class="choice" data-answer="square" aria-pressed="false"><span class="shape square" aria-hidden="true"></span><span>المربع</span></button></div><p class="child-feedback" id="feedback" role="status" aria-live="polite">خذ وقتك، يمكنك أن تجرّب!</p><button id="next-step" class="btn dark" hidden>لنكتشف شيئًا حولنا ←</button><button id="finish-step" class="btn dark" hidden>وجدنا شيئًا دائريًا! ✓</button><button id="restart-step" class="btn white" hidden>نكتشف من جديد ↻</button></section><div class="child-footer"><p>نشاط قصير مع ولي الأمر.<br><span class="micro">يمكنكما التوقف في أي وقت.</span></p><a class="btn line" href="parent.html">نأخذ استراحة ♡</a></div><section class="child-card"><div><h3>خارج الشاشة، تستمر الحكاية.</h3><p>ابحثا عن الأشكال في الغرفة، واحكيا عن الأشياء التي لاحظتماها.</p></div><span class="flower-shape" aria-hidden="true">✦</span></section><p class="micro" style="margin-top:19px">النشاط والأعمار نماذج تحتاج مراجعة تربوية. العودة هنا رابط معاينة؛ حماية مساحة ولي الأمر تُطبّق في الخادم عند التنفيذ.</p></main>'''
(O/'child.html').write_text(head('مساحة الطفل',child),encoding='utf-8')
rows=''
for title,sub,kind,priority,status in [('أشكال من حولنا','نشاط · نسخة ٢','محتوى تربوي','مراجعة تربوية','pending'),('روضة البراعم','طلب انضمام مؤسسة','مؤسسة','بحاجة لاستكمال','pending'),('كيف نحكي قصة؟','نشاط · نسخة ١','محتوى تربوي','جاهز للمراجعة','ready')]:
 rows+=f'<tr data-status="{status}"><td><strong>{title}</strong><span class="micro">{sub}</span></td><td>{kind}</td><td><span class="tag {"pink" if status=="pending" else "yellow"}">{priority}</span></td><td>١٦ سبتمبر</td><td><button class="btn line small" data-review>مراجعة ←</button></td></tr>'
admin=f'''<div class="app admin">{sidebar('admin',True)}<div class="app-body">{header('نبوغ / إدارة المحتوى')}<main class="workspace" id="main"><div class="greeting"><div><span class="eyebrow">مساحة عمل الفريق</span><h1>قرارات صغيرة. تجربة أفضل.</h1><p class="muted">الطلبات التي تحتاج مراجعتك، في مكان واحد.</p></div><span class="tag">مراجع محتوى · نطاق توضيحي</span></div><div class="callout"><strong>قبل اعتماد أي نشاط:</strong> تأكد من ملاءمة العمر، وضوح التعليمات، وسلامة الأدوات.</div><section class="metrics"><div class="metric"><span class="micro">طلبات في قائمة اليوم</span><strong>٣</strong><span class="tag pink">تحتاج مراجعة</span></div><div class="metric"><span class="micro">أنشطة ضمن القائمة</span><strong>٢</strong><span class="micro">في هذا المثال</span></div><div class="metric"><span class="micro">طلبات مؤسسات</span><strong>١</strong><span class="micro">في هذا المثال</span></div></section><section class="queue" id="requests"><div class="queue-header"><div><h2>قائمة المراجعة</h2><p class="micro">الأرقام والطلبات توضيحية، ولا تمثل حالة المنصة الفعلية.</p></div><span class="tag">الأحدث أولًا</span></div><div class="filters"><input class="search-input" type="search" id="queue-search" placeholder="ابحث باسم النشاط أو المؤسسة" aria-label="بحث في قائمة المراجعة"><div class="chip-group"><button class="chip" data-filter="all" aria-pressed="true">الكل</button><button class="chip" data-filter="pending" aria-pressed="false">قيد المراجعة</button><button class="chip" data-filter="ready" aria-pressed="false">جاهز</button></div></div><div class="table-wrap"><table><thead><tr><th>الطلب</th><th>النوع</th><th>الحالة</th><th>أُضيف في</th><th>الإجراء</th></tr></thead><tbody id="queue-body">{rows}</tbody></table></div><div class="table-footer" id="queue-count" role="status">عرض ٣ طلبات تجريبية</div></section><div class="lower-grid"><section class="card"><span class="eyebrow">عند تنفيذ النظام</span><h3>قرار واضح، وسجل يمكن الرجوع إليه.</h3><p class="muted">ترتبط كل مراجعة بصاحب القرار ووقته وسبب الاعتماد أو طلب التعديل.</p></section><section class="card coach"><h3>ما الذي يسبق النشر؟</h3><p>مسودة ← مراجعة تربوية ← اعتماد ← نشر.<br>تظهر الإجراءات بحسب الصلاحية الفعلية.</p></section></div></main></div></div><dialog class="dialog" id="review-dialog"><div class="dialog-body"><div class="dialog-head"><h2 id="review-title">مراجعة الطلب</h2><button class="icon-btn" data-close aria-label="إغلاق">×</button></div><span class="tag yellow">معاينة إجراء إداري</span><p style="margin-top:18px">هذا المثال يشرح الانتقال بين الحالات فقط. في المنتج، يُرفق نص النشاط ومعايير المراجعة، وتتحقق الصلاحيات في الخادم قبل إتمام القرار.</p><div class="actions" style="margin-top:25px"><button class="btn dark" id="approve-demo">اعتماد في المعاينة</button><button class="btn line" data-close>عودة للقائمة</button></div></div></dialog>'''
